-- Regional pack Eastern Kingdoms, Ironforge (content wave W01: the forge city under the mountain, its rings and its halls). Written through the authoring archive
-- (tools/archive, CONTRIBUTING.md); the texts are in AzerothUnspoken_EasternKingdoms_enUS/Ironforge.lua and AzerothUnspoken_EasternKingdoms_itIT/Ironforge.lua. Built while
-- the character is in the area "dunmorogh" and dropped when it leaves it (ADR 0048); the folder is loaded with the region
-- (ADR 0025). Races, classes, weather, the time of day and the moment are conditions inside the rules, never separate
-- packs. Subzone names are those of the English Classic client and are not yet confirmed in Forever (#36): a wrong
-- name only keeps a line silent.
local AU = AzerothUnspoken

